#!/usr/bin/env node

import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const projectDirectory = dirname(fileURLToPath(import.meta.url));
const sharedProjectDirectory = join(projectDirectory, "../PDF-OCR_開発用");
const outputPath = join(projectDirectory, "ScanScribe-Image.html");

function sha256Source(source) {
  return `'sha256-${createHash("sha256").update(source, "utf8").digest("base64")}'`;
}

function assertRawTextSafe(source, tagName, sourceName) {
  if (new RegExp(`</${tagName}`, "i").test(source)) {
    throw new Error(`${sourceName} contains a closing ${tagName} tag and cannot be embedded safely.`);
  }
}

function stripSourceMapReference(source) {
  return source.replace(/^[ \t]*\/\/[#@]\s*sourceMappingURL=.*?(?:\r?\n|$)/gm, "");
}

function replaceExactlyOnce(source, searchValue, replacement, label) {
  const firstIndex = source.indexOf(searchValue);
  if (firstIndex < 0 || source.indexOf(searchValue, firstIndex + searchValue.length) >= 0) {
    throw new Error(`Expected exactly one ${label} in index.html.`);
  }
  return source.replace(searchValue, replacement);
}

let html = await readFile(join(projectDirectory, "index.html"), "utf8");
const [cssSource, thirdPartyNotices] = await Promise.all([
  readFile(join(projectDirectory, "styles.css"), "utf8"),
  readFile(join(projectDirectory, "THIRD_PARTY_NOTICES.md"), "utf8"),
]);
const css = cssSource.trimEnd();
assertRawTextSafe(css, "style", "./styles.css");

html = replaceExactlyOnce(
  html,
  '<html lang="ja">',
  '<html lang="ja" data-single-file="true" data-variant="image-precision">',
  "root html tag",
);
const styleContent = `\n${css}\n    `;
html = replaceExactlyOnce(
  html,
  '    <link rel="stylesheet" href="./styles.css">',
  `    <style data-bundled-source="./styles.css">${styleContent}</style>`,
  "stylesheet reference",
);

const scriptEntries = [
  {
    htmlPath: "../PDF-OCR_開発用/offline-guard.js",
    diskPath: join(sharedProjectDirectory, "offline-guard.js"),
  },
  {
    htmlPath: "../PDF-OCR_開発用/browser-compat.js",
    diskPath: join(sharedProjectDirectory, "browser-compat.js"),
  },
  {
    htmlPath: "../PDF-OCR_開発用/vendor/tesseract.min.js",
    diskPath: join(sharedProjectDirectory, "vendor/tesseract.min.js"),
  },
  {
    htmlPath: "../PDF-OCR_開発用/vendor-precision/offline-ocr-assets.js",
    diskPath: join(sharedProjectDirectory, "vendor-precision/offline-ocr-assets.js"),
  },
  {
    htmlPath: "../PDF-OCR_開発用/ocr-core.js",
    diskPath: join(sharedProjectDirectory, "ocr-core.js"),
  },
  {
    htmlPath: "../PDF-OCR_開発用/accuracy-core.js",
    diskPath: join(sharedProjectDirectory, "accuracy-core.js"),
  },
  {
    htmlPath: "./image-core.js",
    diskPath: join(projectDirectory, "image-core.js"),
  },
  {
    htmlPath: "./app.js",
    diskPath: join(projectDirectory, "app.js"),
  },
];
const embeddedScripts = [];
const scriptHashes = [];
for (const entry of scriptEntries) {
  const source = stripSourceMapReference(
    await readFile(entry.diskPath, "utf8"),
  ).trimEnd();
  assertRawTextSafe(source, "script", entry.htmlPath);
  const scriptContent = `\n${source}\n    `;
  scriptHashes.push(sha256Source(scriptContent));
  embeddedScripts.push(
    `    <script data-bundled-source="${entry.htmlPath}">${scriptContent}</script>`,
  );
  html = replaceExactlyOnce(
    html,
    `    <script defer src="${entry.htmlPath}"></script>\n`,
    "",
    `script reference for ${entry.htmlPath}`,
  );
}

const csp = [
  "default-src 'none'",
  `script-src ${scriptHashes.join(" ")} 'wasm-unsafe-eval'`,
  `style-src ${sha256Source(styleContent)}`,
  "worker-src blob:",
  "child-src blob:",
  "connect-src 'none'",
  "img-src data: blob:",
  "font-src data: blob:",
  "media-src 'none'",
  "object-src 'none'",
  "frame-src 'none'",
  "manifest-src 'none'",
  "base-uri 'none'",
  "form-action 'none'",
].join("; ");
const cspPattern = /(<meta\s+http-equiv="Content-Security-Policy"\s+content=")[^"]*("\s*>)/;
if (!cspPattern.test(html)) throw new Error("Content-Security-Policy meta tag was not found.");
html = html.replace(cspPattern, `$1${csp}$2`);
html = replaceExactlyOnce(
  html,
  "  </body>",
  `${embeddedScripts.join("\n")}\n  </body>`,
  "closing body tag",
);
const safeNotices = thirdPartyNotices.trim().replaceAll("--", "- -");
html = replaceExactlyOnce(
  html,
  "</html>",
  `<!--\nBundled third-party notices:\n\n${safeNotices}\n-->\n</html>`,
  "closing html tag",
);
html = html.replace(
  "<!doctype html>",
  "<!doctype html>\n<!-- Generated by image-ocr/build-single-html.mjs. All runtime assets are embedded below. -->",
);

await writeFile(outputPath, html, "utf8");
const outputBytes = Buffer.byteLength(html, "utf8");
const outputHash = createHash("sha256").update(html, "utf8").digest("hex");
console.log(`Created ${outputPath}`);
console.log(`Size: ${(outputBytes / 1024 / 1024).toFixed(1)} MiB`);
console.log(`SHA-256: ${outputHash}`);
